// Some portions generated by Codex
package org.eclipse.rdf4j.sail.nativerdf.wal;

import static org.assertj.core.api.Assertions.assertThat;

import java.nio.file.Files;
import java.nio.file.Path;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class GH6400WriterSegmentCollisionReviewTest {

	@TempDir
	Path directory;

	@Test
	void reopeningWithRepeatedFirstIdPreservesOriginalSegment() throws Exception {
		ValueStoreWalConfig config = config(128 * 1024);
		try (ValueStoreWAL wal = ValueStoreWAL.open(config)) {
			wal.logMint(1, ValueStoreWalValueKind.LITERAL, "original", "", "", 0);
		}
		Path original = directory.resolve("wal-1.v1");
		byte[] originalBytes = Files.readAllBytes(original);
		try (ValueStoreWAL wal = ValueStoreWAL.open(config)) {
			wal.logMint(1, ValueStoreWalValueKind.LITERAL, "retried", "", "", 0);
		}

		assertThat(Files.readAllBytes(original)).containsExactly(originalBytes);
		assertThat(directory.resolve("wal-1-2.v1")).exists();
		try (ValueStoreWalReader reader = ValueStoreWalReader.open(config)) {
			var result = reader.scan();
			assertThat(result.complete()).isTrue();
			assertThat(result.records()).extracting(ValueStoreWalRecord::lexical)
					.containsExactly("original", "retried");
		}
	}

	@Test
	void rotationPreservesCompressedSegmentsWithRepeatedFirstId() throws Exception {
		ValueStoreWalConfig config = config(4096);
		String large = "x".repeat(8192);
		try (ValueStoreWAL wal = ValueStoreWAL.open(config)) {
			wal.logMint(1, ValueStoreWalValueKind.LITERAL, large, "", "", 0);
			wal.logMint(1, ValueStoreWalValueKind.LITERAL, "retried", "", "", 0);
		}

		assertThat(directory.resolve("wal-1.v1.gz")).exists();
		assertThat(directory.resolve("wal-1-2.v1.gz")).exists();
		assertThat(directory.resolve("wal-1-3.v1")).exists();
		try (ValueStoreWalReader reader = ValueStoreWalReader.open(config)) {
			var result = reader.scan();
			assertThat(result.complete()).isTrue();
			assertThat(result.records()).extracting(ValueStoreWalRecord::lexical)
					.containsExactly(large, "retried");
		}
	}

	private ValueStoreWalConfig config(long maxSegmentBytes) {
		return ValueStoreWalConfig.builder()
				.walDirectory(directory)
				.storeUuid("segment-collision-review")
				.maxSegmentBytes(maxSegmentBytes)
				.syncPolicy(ValueStoreWalConfig.SyncPolicy.COMMIT)
				.build();
	}
}
